package br.com.bancohorizonte.http;
import br.com.bancohorizonte.config.JpaConfig; import br.com.bancohorizonte.controller.*; import br.com.bancohorizonte.dto.*; import br.com.bancohorizonte.exception.*; import br.com.bancohorizonte.service.*; import com.sun.net.httpserver.*; import jakarta.persistence.EntityManager; import java.io.*; import java.util.*;
public class ApiHandler implements HttpHandler { public void handle(HttpExchange ex)throws IOException { try(EntityManager em=JpaConfig.entityManager()){PessoaController pessoas=new PessoaController(new PessoaService(em));ContaController contas=new ContaController(new ContaService(em));String method=ex.getRequestMethod();String path=ex.getRequestURI().getPath();Object response;int status=200;if(method.equals("POST")&&path.equals("/api/pessoas")){response=pessoas.criar(Json.ler(ex.getRequestBody(),PessoaRequest.class));status=201;}else if(method.equals("POST")&&path.equals("/api/contas")){response=contas.abrir(Json.ler(ex.getRequestBody(),AbrirContaRequest.class));status=201;}else if(method.equals("GET")&&path.matches("/api/contas/pessoa/\\d+")){response=contas.listarPorPessoa(id(path));}else if(method.equals("GET")&&path.matches("/api/contas/\\d+")){response=contas.buscar(id(path));}else if(method.equals("PATCH")&&path.matches("/api/contas/\\d+/depositos")){response=contas.depositar(id(path),Json.ler(ex.getRequestBody(),MovimentacaoRequest.class));}else if(method.equals("PATCH")&&path.matches("/api/contas/\\d+/saques")){response=contas.sacar(id(path),Json.ler(ex.getRequestBody(),MovimentacaoRequest.class));}else {Json.responder(ex,404,new ErroResponse(404,"Rota não encontrada."));return;}Json.responder(ex,status,response);}catch(Exception e){tratar(ex,e);} } private Long id(String path){String[] p=path.split("/");return Long.valueOf(p[path.contains("/pessoa/")?4:3]);} private void tratar(HttpExchange ex,Exception e)throws IOException {Throwable t=e instanceof java.io.UncheckedIOException?e.getCause():e;int s=(t instanceof PessoaNaoEncontradaException||t instanceof ContaNaoEncontradaException||t instanceof TipoContaNaoEncontradoException)?404:(t instanceof CpfJaCadastradoException||t instanceof ContaJaCadastradaException||t instanceof ContaInativaException||t instanceof SaldoInsuficienteException)?409:400;String msg=t instanceof BusinessException?t.getMessage():"JSON inválido ou erro interno na requisição.";Json.responder(ex,s,new ErroResponse(s,msg));} }
